import{_ as e,C as t,c as n,o as a,j as i,b as l,a0 as d,a as r,w as o,G as s,a1 as g}from"./chunks/framework.DKRgXLPU.js";const h=JSON.parse('{"title":"Je trainingsplan opstellen","description":"","frontmatter":{},"headers":[],"relativePath":"nl/education/goals/planning.md","filePath":"nl/education/goals/planning.md"}');const u=e({name:"nl/education/goals/planning.md"},[["render",function(e,h,u,p,k,c){const m=t("Mermaid");return a(),n("div",null,[h[1]||(h[1]=i("h1",{id:"je-trainingsplan-opstellen",tabindex:"-1"},[r("Je trainingsplan opstellen "),i("a",{class:"header-anchor",href:"#je-trainingsplan-opstellen","aria-label":'Permalink to "Je trainingsplan opstellen"'},"​")],-1)),h[2]||(h[2]=i("p",null,"Doelen zonder plan blijven slechts wensen. Deze gids helpt je om je doelen om te zetten in een gestructureerd trainingsplan dat daadwerkelijk werkt.",-1)),h[3]||(h[3]=i("div",{class:"tip custom-block"},[i("p",{class:"custom-block-title"},"Het Grote Idee"),i("p",null,[i("strong",null,"Doelen zonder plan zijn slechts wensen."),r(" Een gestructureerd trainingsplan zet je doelen om in dagelijkse acties die leiden tot echte vooruitgang.")])],-1)),(a(),l(g,null,{default:o(()=>[s(m,{id:"mermaid-11",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BDoel%5D%20--%3E%20B%5BTrainingsplan%5D%0A%20%20%20%20B%20--%3E%20C%5BDagelijkse%20acties%5D%0A%20%20%20%20C%20--%3E%20D%5BConsistente%20praktijk%5D%0A%20%20%20%20D%20--%3E%20E%5BMeetbare%20vooruitgang%5D%0A%20%20%20%20E%20--%3E%20F%5BDoelbereiking%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20B%20fill%3A%23e8f5e9%0A%20%20%20%20style%20C%20fill%3A%23fff4e1%0A%20%20%20%20style%20F%20fill%3A%23fff4e1%0A"})]),fallback:o(()=>[...h[0]||(h[0]=[r(" Loading... ",-1)])]),_:1})),h[4]||(h[4]=d('<h2 id="de-8-fasen-van-zelfgestuurde-ontwikkeling" tabindex="-1">De 8 fasen van zelfgestuurde ontwikkeling <a class="header-anchor" href="#de-8-fasen-van-zelfgestuurde-ontwikkeling" aria-label="Permalink to &quot;De 8 fasen van zelfgestuurde ontwikkeling&quot;">​</a></h2><h3 id="fase-1-stel-je-kompas-in-doelen" tabindex="-1">Fase 1: Stel je kompas in (Doelen) <a class="header-anchor" href="#fase-1-stel-je-kompas-in-doelen" aria-label="Permalink to &quot;Fase 1: Stel je kompas in (Doelen)&quot;">​</a></h3><p>Je hebt al geleerd over SMART-doelen. Plaats ze nu in een hiërarchie:</p><ol><li><strong>Langetermijndoel</strong> (1-2 jaar): Jouw droom</li><li><strong>Jaarlijks doel</strong>: Doelstelling voor dit jaar</li><li><strong>Doelstellingen per kwartaal</strong>: mijlpalen per 3 maanden</li><li><strong>Maandelijkse doelen</strong>: Specifieke aandachtsgebieden</li><li><strong>Wekelijkse doelen</strong>: Trainingsdoelen</li></ol><h3 id="fase-2-beoordeel-uw-middelen" tabindex="-1">Fase 2: Beoordeel uw middelen <a class="header-anchor" href="#fase-2-beoordeel-uw-middelen" aria-label="Permalink to &quot;Fase 2: Beoordeel uw middelen&quot;">​</a></h3><p>Voordat je begint met plannen, moet je eerlijk evalueren wat je hebt:</p><table tabindex="0"><thead><tr><th>Bron</th><th>Vragen om te stellen</th></tr></thead><tbody><tr><td><strong>Tijd</strong></td><td>Hoeveel uur per week kun je realistisch gezien trainen?</td></tr><tr><td><strong>Locatie</strong></td><td>Heb je toegang tot een goede piste? Hoe is de kwaliteit van het oppervlak?</td></tr><tr><td><strong>Apparatuur</strong></td><td>Beschikt u over geschikte boules? Meetinstrumenten? Video-opnameapparatuur?</td></tr><tr><td><strong>Kennis</strong></td><td>Wat zijn je technische sterke en zwakke punten?</td></tr><tr><td><strong>Fysieke conditie</strong></td><td>Zijn er beperkingen? Gebieden die verbetering behoeven?</td></tr></tbody></table><p>Wees eerlijk. Een realistisch plan is beter dan een ambitieuze fantasie.</p><h3 id="fase-3-kies-je-oefeningen" tabindex="-1">Fase 3: Kies je oefeningen <a class="header-anchor" href="#fase-3-kies-je-oefeningen" aria-label="Permalink to &quot;Fase 3: Kies je oefeningen&quot;">​</a></h3><p>Kies oefeningen die direct aansluiten bij je doelen:</p><p><strong>Ter verbetering van de aanwijsvaardigheden:</strong></p><ul><li>Nauwkeurig aanwijzen van gemarkeerde zones</li><li>Oefeningen met variatie in afstand</li><li>Verschillende ondergronden</li></ul><p><strong>Tip voor betere opnames:</strong></p><ul><li>Schietladder (oplopende afstanden)</li><li>Schieten over een obstakel (gedwongen hoge boog)</li><li>Oefening met bewegend doelwit</li></ul><p><strong>Voor mentale ontwikkeling:</strong></p><ul><li>Oefening van de voorbereiding op de opname</li><li>Visualisatiesessies</li><li>Druksimulatie</li></ul><p><strong>Breng balans in je programma:</strong></p><ul><li>Technische werkzaamheden (richten, filmen)</li><li>Mentale training (mindfulness, visualisatie)</li><li>Fysieke conditie (balans, flexibiliteit)</li><li>Wedstrijdspel (vaardigheden toepassen)</li></ul><h3 id="fase-4-stel-je-planning-samen" tabindex="-1">Fase 4: Stel je planning samen <a class="header-anchor" href="#fase-4-stel-je-planning-samen" aria-label="Permalink to &quot;Fase 4: Stel je planning samen&quot;">​</a></h3><p>Stel een realistisch weekschema op:</p><table tabindex="0"><thead><tr><th>Dag</th><th>Ochtend</th><th>Middag</th><th>Avond</th><th>Focus</th></tr></thead><tbody><tr><td>ma</td><td>-</td><td>Technisch: Aanwijzen</td><td>Lichte mobiliteit</td><td>Precisie</td></tr><tr><td>di</td><td>-</td><td>Technisch: Opnames</td><td>-</td><td>Vermogen/nauwkeurigheid</td></tr><tr><td>woensdag</td><td>-</td><td>Mentale training</td><td>-</td><td>Mindfulness</td></tr><tr><td>Do</td><td>-</td><td>Gemengd: Spelscenario&#39;s</td><td>Lichte mobiliteit</td><td>Sollicitatie</td></tr><tr><td>vr</td><td>-</td><td>Technisch: Zwakte</td><td>-</td><td>Verbetering</td></tr><tr><td>Zat</td><td>Wedstrijd of competitie</td><td>-</td><td>-</td><td>Prestatie</td></tr><tr><td>Zon</td><td>Rest</td><td>Wekelijkse evaluatie</td><td>Planning</td><td>Herstel</td></tr></tbody></table><p><strong>Belangrijkste principes:</strong></p><ul><li>Geef prioriteit aan mentale training (dit wordt vaak verwaarloosd).</li><li>Neem rustdagen mee in de planning.</li><li>Breng verschillende vaardigheden in balans.</li><li>Behoud flexibiliteit voor het leven.</li></ul><h3 id="fase-5-bereid-je-voor-op-obstakels" tabindex="-1">Fase 5: Bereid je voor op obstakels <a class="header-anchor" href="#fase-5-bereid-je-voor-op-obstakels" aria-label="Permalink to &quot;Fase 5: Bereid je voor op obstakels&quot;">​</a></h3><p>Er zullen dingen misgaan. Houd daar rekening mee.</p><table tabindex="0"><thead><tr><th>Risico</th><th>Waarschijnlijkheid</th><th>Invloed</th><th>Back-upplan</th></tr></thead><tbody><tr><td>Tijdgebrek</td><td>Hoog</td><td>Medium</td><td>Zorg dat je een &quot;minimale sessie&quot; klaar hebt (20 minuten).</td></tr><tr><td>Slecht weer</td><td>Medium</td><td>Medium</td><td>Binnenvisualisatie, videostudie</td></tr><tr><td>Lage motivatie</td><td>Hoog</td><td>Medium</td><td>Keer terug naar het &quot;waarom&quot;, stel kleinere doelen en neem een pauze.</td></tr><tr><td>Lichte verwonding</td><td>Medium</td><td>Hoog</td><td>Focus op mentale training, vaardigheden die niet aangetast zijn.</td></tr><tr><td>Geen oefenpartner</td><td>Medium</td><td>Laag</td><td>Solo-oefeningen, zelfanalyse via video</td></tr></tbody></table><h3 id="fase-6-houd-je-voortgang-bij" tabindex="-1">Fase 6: Houd je voortgang bij <a class="header-anchor" href="#fase-6-houd-je-voortgang-bij" aria-label="Permalink to &quot;Fase 6: Houd je voortgang bij&quot;">​</a></h3><p>Wat gemeten wordt, kan beheerd worden.</p><p><strong>Houd een trainingsdagboek bij:</strong></p><ul><li>Datum en duur</li><li>Voltooide oefeningen</li><li>Uitslagen/resultaten</li><li>Hoe je je voelde (energie, focus, flow)</li><li>Technische notities</li><li>Weer/omstandigheden</li></ul><p><strong>Wekelijkse evaluatievragen:</strong></p><ul><li>Heb ik mijn geplande sessies afgerond?</li><li>Welke scores heb ik behaald?</li><li>Wat voelde goed? Wat was moeilijk?</li><li>Heb je wel eens een flow-ervaring gehad?</li><li>Wat moet ik aanpassen?</li></ul><h3 id="fase-7-blijf-gemotiveerd" tabindex="-1">Fase 7: Blijf gemotiveerd <a class="header-anchor" href="#fase-7-blijf-gemotiveerd" aria-label="Permalink to &quot;Fase 7: Blijf gemotiveerd&quot;">​</a></h3><p>Motivatie fluctueert. Ontwikkel systemen om die motivatie te behouden:</p><p><strong>Interne motivatie:</strong></p><ul><li>Verbind je met je &quot;waarom&quot;.</li><li>Vier de kleine successen.</li><li>Merk na verloop van tijd verbetering op.</li><li>Vind plezier in het proces.</li></ul><p><strong>Externe ondersteuning:</strong></p><ul><li>Trainingspartners (zelfs af en toe)</li><li>Deel je doelen met iemand.</li><li>Sluit je aan bij online communities</li><li>Volg reeksen en consistentie</li></ul><p><strong>Wanneer de motivatie afneemt:</strong></p><ul><li>Doe in ieder geval een korte sessie (iets is beter dan niets).</li><li>Verander je omgeving.</li><li>Bekijk je voortgang</li><li>Denk terug aan successen uit het verleden.</li><li>Neem indien nodig een geplande pauze.</li></ul><h3 id="fase-8-evalueren-en-aanpassen" tabindex="-1">Fase 8: Evalueren en aanpassen <a class="header-anchor" href="#fase-8-evalueren-en-aanpassen" aria-label="Permalink to &quot;Fase 8: Evalueren en aanpassen&quot;">​</a></h3><p>Je plan moet zich ontwikkelen:</p><p><strong>Wekelijks:</strong> Snelle evaluatie, kleine aanpassingen <strong>Maandelijks:</strong> Evalueer de voortgang richting de maandelijkse doelen en pas de focus aan. <strong>Kwartaaloverzicht:</strong> Grote evaluatie, vaststellen van de doelen voor het volgende kwartaal <strong>Jaarlijks:</strong> Volledige evaluatie, nieuw jaarplan</p><p><strong>Vragen ter beoordeling:</strong></p><ul><li>Boek ik vooruitgang in het bereiken van mijn doelen?</li><li>Is mijn training effectief?</li><li>Heb ik andere oefeningen nodig?</li><li>Zijn mijn doelen nog steeds relevant?</li><li>Wat heb ik geleerd?</li></ul><h2 id="voorbeeld-van-een-8-wekenplan" tabindex="-1">Voorbeeld van een 8-wekenplan <a class="header-anchor" href="#voorbeeld-van-een-8-wekenplan" aria-label="Permalink to &quot;Voorbeeld van een 8-wekenplan&quot;">​</a></h2><p><strong>Doel:</strong> De schietnauwkeurigheid met 15% verbeteren.</p><table tabindex="0"><thead><tr><th>Week</th><th>Focus</th><th>Belangrijke sessies</th></tr></thead><tbody><tr><td>1</td><td>Basislijn</td><td>Test het huidige niveau, videoanalyse</td></tr><tr><td>2</td><td>Techniek</td><td>Identificeer en werk aan het belangrijkste probleem.</td></tr><tr><td>3</td><td>Herhaling</td><td>Schietoefeningen met een hoog volume</td></tr><tr><td>4</td><td>Test</td><td>Tussentijdse beoordeling, aanpassen</td></tr><tr><td>5</td><td>Variatie</td><td>Verschillende afstanden en hoeken</td></tr><tr><td>6</td><td>Druk</td><td>Voeg consequenties toe aan oefeningen.</td></tr><tr><td>7</td><td>Integratie</td><td>Spelachtige scenario&#39;s</td></tr><tr><td>8</td><td>Eindtoets</td><td>Verbetering meten</td></tr></tbody></table><h2 id="belangrijkste-conclusie" tabindex="-1">Belangrijkste conclusie <a class="header-anchor" href="#belangrijkste-conclusie" aria-label="Permalink to &quot;Belangrijkste conclusie&quot;">​</a></h2><blockquote><p>Maak een plan voor je werk en voer dat plan vervolgens uit. Maar wees wel bereid om je aan te passen.</p></blockquote><p>Het beste plan is een plan dat je ook daadwerkelijk volgt. Begin eenvoudig, blijf consequent en pas het aan naarmate je meer leert.</p>',51))])}]]);export{h as __pageData,u as default};
